import Distributions: quantile, Normal
import JSON

"""
	gen( p, mu, sigma, name )

Generate fixture data and write to file.

# Arguments

* `p`: probabilities
* `mu`: mean
* `sigma`: standard deviation
* `name::AbstractString`: output filename

# Examples

``` julia
julia> p = rand( 1000 );
julia> mu = rand( 1000 );
julia> sigma = rand( 1000 ) .+ 0.1;
julia> gen( p, mu, sigma, "data.json" );
```
"""
function gen( p, mu, sigma, name )
	z = Array{Float64}( undef, length( p ) );

	# Evaluate the quantile function in extended precision, and round the result to double precision:
	setprecision( BigFloat, 2048 ) do
		for i in eachindex( p )
			z[ i ] = Float64( quantile( Normal( BigFloat( mu[ i ] ), BigFloat( sigma[ i ] ) ), BigFloat( p[ i ] ) ) );
		end
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("p", p),
		("mu", mu),
		("sigma", sigma),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Probabilities in the lower tail, down to `1e-250`:
p = exp10.( rand( 500 ) .* -247.0 .- 3.0 );
mu = ( rand( 500 ) .* 20.0 ) .- 10.0;
sigma = ( rand( 500 ) .* 10.0 ) .+ 0.1;
gen( p, mu, sigma, "lower_tail.json" );

# Probabilities in the upper tail, up to the largest double less than `1`:
p = 1.0 .- exp10.( rand( 500 ) .* -13.0 .- 3.0 );
mu = ( rand( 500 ) .* 20.0 ) .- 10.0;
sigma = ( rand( 500 ) .* 10.0 ) .+ 0.1;
gen( p, mu, sigma, "upper_tail.json" );
